3a\u043b\u043e\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f.\n- \u0412\u044b\u0432\u043e\u0434: **\u043d\u0438 \u043e\u0434\u0438\u043d \u043f\u0443\u043d\u043a\u0442 \u0438\u0437 \u0438\u0441\u0445\u043e\u0434\u043d\u0438\u043a\u043e\u0432 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f**. \u0412\u0441\u0451 \u043d\u0438\u0436\u0435 \u043e\u043f\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0435 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0435\u0432 `FlowingML/JaxMARL` \u0438 `FlowingML/SMAX` (README, paper NeurIPS 2023 D&B, \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u043a\u043e\u0434\u0430) \u0438 \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u043e \u043a\u0430\u043a \u00ab\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e \u043f\u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430\u043c\u00bb \u043b\u0438\u0431\u043e \u00ab\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435\u00bb. \u0415\u0441\u043b\u0438 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044e \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439, \u043f\u0435\u0440\u0435\u0447\u0435\u043d\u044c \u00ab\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e \u043f\u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430\u043c\u00bb \u0441\u0442\u043e\u0438\u0442 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e \u0444\u0430\u0439\u043b\u0430\u043c.\n\n### 1. \u0427\u0442\u043e \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e \u043e JaxMARL / SMAX (\u043f\u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430\u043c)\n- **\u0420\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f PPO**: `jaxmarl/algorithms/ppo/` (\u0432\u0435\u043a\u0442\u043e\u0440\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0439 IPPO-\u0441\u0442\u0438\u043b\u044c, \u043e\u0431\u0449\u0430\u044f \u0441\u0435\u0442\u044c \u043d\u0430 \u0432\u0441\u0435\u0445 \u0430\u0433\u0435\u043d\u0442\u043e\u0432), \u043a\u043e\u043d\u0444\u0438\u0433 \u0432 `config.py`, \u043f\u0440\u0438\u043c\u0435\u0440 `jaxmarl/examples/smax_ppo.py`. \u0414\u0435\u0444\u043e\u043b\u0442\u044b CleanRL-\u0441\u0442\u0438\u043b\u044f: lr=2.5e-4, gamma=0.99, gae_lambda=0.95, clip_coef=0.2, ent_coef=0.01, vf_coef=0.5, max_grad_norm=0.5, update_epochs=4, num_minibatches=32, anneal_lr=True. **(\u043f\u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430\u043c; \u0442\u043e\u0447\u043d\u044b\u0435 \u043f\u043e\u043b\u044f \u0444\u0430\u0439\u043b\u0430 \u2014 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435).**\n- **Q-learning \u0431\u0435\u0439\u0437\u043b\u0430\u0439\u043d**: \u0432 JaxMARL \u0435\u0441\u0442\u044c `jaxmarl/algorithms/iql/` (Independent Q-learning, DQN-\u0441\u0442\u0438\u043b\u044c, replay buffer). \u041d\u0430\u043b\u0438\u0447\u0438\u0435 \u0433\u043e\u0442\u043e\u0432\u043e\u0433\u043e **QMIX** (`jaxmarl/algorithms/qmix/`) \u2014 \u043f\u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0439 \u043f\u0430\u043c\u044f\u0442\u0438 \u0435\u0441\u0442\u044c, \u043d\u043e **\u043d\u0435 \u0443\u0432\u0435\u0440\u0435\u043d \u2192 \u044d\u0442\u043e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435/\u043f\u0443\u043d\u043a\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438**. \u042d\u0442\u043e \u0432\u0430\u0436\u043d\u043e: \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u00abQ-learning\u00bb vs \u00abvalue-decomposition\u00bb \u043c\u0435\u043d\u044f\u0435\u0442 \u0441\u043c\u044b\u0441\u043b \u0432\u044b\u0432\u043e\u0434\u0430.\n- **SMAX \u043a\u0430\u0440\u0442\u044b**: `MapName`-\u044d\u043d\u0430\u043c \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439 SMAC-\u043d\u0430\u0431\u043e\u0440: 3m, 8m, 2s3z, 5m_vs_6m, 10m_vs_11m, MMM2, corridor, 3s5z, 1c3s5z, 2c_vs_64zg, bane_vs_bane, 3s_vs_5z, 6h_vs_8z \u0438 \u0434\u0440. \u0422\u043e\u0447\u043d\u043e \u043a\u0430\u043a\u043e\u0439 \u043f\u043e\u0434\u043d\u0430\u0431\u043e\u0440 \u0440\u0435\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d \u2014 **\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435** (\u0441\u043f\u0438\u0441\u043e\u043a \u043d\u0430\u0434\u043e \u0441\u0432\u0435\u0440\u044f\u0442\u044c \u043f\u043e `smax/maps/`).\n- **Evaluation / \u043d\u0430\u0433\u0440\u0430\u0434\u044b**: \u0432 `smax_ppo.py` eval-\u0432\u0438\u043d\u0440\u0435\u0439\u0442 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0434\u043e\u043b\u044f eval-\u044d\u043f\u0438\u0437\u043e\u0434\u043e\u0432, \u0433\u0434\u0435 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u043d\u0430\u0433\u0440\u0430\u0434\u0430 \u044d\u043f\u0438\u0437\u043e\u0434\u0430 == 1 (\u043f\u043e\u0431\u0435\u0434\u0430); SMAX-\u043d\u0430\u0433\u0440\u0430\u0434\u0430 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u043d\u043e\u0440\u043c\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0431\u043b\u0443\u0436\u0434\u0430\u044e\u0449\u0438\u043c \u0441\u0440\u0435\u0434\u043d\u0438\u043c \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u0430 \u044d\u043f\u0438\u0437\u043e\u0434\u0430 (`normalize_reward`), \u043f\u043b\u044e\u0441 dense-\u043d\u0430\u0433\u0440\u0430\u0434\u0430 \u0437\u0430 \u0443\u0440\u043e\u043d \u0438 sparse +1/\u22121 \u0437\u0430 \u043f\u043e\u0431\u0435\u0434\u0443/\u043f\u043e\u0440\u0430\u0436\u0435\u043d\u0438\u0435. **(\u043f\u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430\u043c; \u0442\u043e\u0447\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0430 \u043d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u043a\u0438 \u2014 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435).**\n\n### 2. \u042d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430\n- **\u041c\u0435\u0442\u0440\u0438\u043a\u0438 (\u043e\u0442\u0432\u0435\u0447\u0430\u044e\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 \u00abtraining time\u00bb \u0438 \u00abnormalized score\u00bb)**:\n  - \u041d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 score = **win rate** \u0438\u0437 SMAX-eval (\u0435\u0434\u0438\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430, \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u043d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u043a\u0438 \u043d\u0430\u0433\u0440\u0430\u0434\u044b). \u0412\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u2014 \u043d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0432\u043e\u0437\u0432\u0440\u0430\u0442 \u044d\u043f\u0438\u0437\u043e\u0434\u0430 (\u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f SMAX \u0447\u0435\u0440\u0435\u0437 \u0431\u043b\u0443\u0436\u0434\u0430\u044e\u0449\u0435\u0435 \u0441\u0440\u0435\u0434\u043d\u0435\u0435).\n  - Training time = **wall-clock (\u0441\u0435\u043a)** \u0434\u043e \u043f\u043e\u0440\u043e\u0433\u0430 win rate + **throughput (steps/s)** + \u0447\u0438\u0441\u043b\u043e timesteps \u0434\u043e \u043f\u043e\u0440\u043e\u0433\u0430. \u041f\u043e\u0440\u043e\u0433\u0438 \u043f\u043e \u043a\u0430\u0440\u0442\u0430\u043c: \u043b\u0451\u0433\u043a\u0438\u0435 90% win, \u0441\u0440\u0435\u0434\u043d\u0438\u0435 70\u201380%, \u0445\u0430\u0440\u0434 \u2014 \u043f\u043e \u0434\u043e\u0441\u0442\u0438\u0436\u0438\u043c\u043e\u0441\u0442\u0438/\u0431\u044e\u0434\u0436\u0435\u0442\u0443.\n- **\u041a\u0430\u0440\u0442\u044b \u0438 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435** (2\u20133 \u0448\u0442., \u0431\u044e\u0434\u0436\u0435\u0442 CPU): 3m (\u043b\u0435\u0433\u043a\u043e, \u043e\u0434\u043d\u043e\u0440\u043e\u0434\u043d\u043e, \u0431\u044b\u0441\u0442\u0440\u043e, \u00absanity\u00bb), 2s3z (\u0440\u0430\u0437\u043d\u043e\u0440\u043e\u0434\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u044f \u044e\u043d\u0438\u0442\u043e\u0432, \u0441\u0440\u0435\u0434\u043d\u044f\u044f), 5m_vs_6m (\u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f, \u043c\u0438\u043a\u0440\u043e-\u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u044c). \u041a\u0430\u0436\u0434\u0430\u044f \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0440\u0430\u0437\u043d\u044b\u0439 \u0440\u0435\u0436\u0438\u043c \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438/\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430; 8m/MMM2 \u2014 \u0437\u0430\u043f\u0430\u0441\u043d\u043e\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442, \u0435\u0441\u043b\u0438 5m_vs_6m \u043e\u043a\u0430\u0436\u0435\u0442\u0441\u044f \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0434\u043e\u0440\u043e\u0433\u043e\u0439 \u043d\u0430 CPU.\n- **\u0413\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b**: \u0431\u0435\u0440\u0451\u043c \u0434\u0435\u0444\u043e\u043b\u0442\u044b \u0438\u0437 JaxMARL config \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430 **\u0431\u0435\u0437 \u043f\u043e\u0434\u0431\u043e\u0440\u0430 \u043f\u043e\u0434 \u043c\u0435\u0442\u0440\u0438\u043a\u0443** (\u0432\u0430\u0436\u043d\u043e \u0434\u043b\u044f \u0447\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u0438 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u00ab\u043a\u043e\u0440\u043e\u0431\u043e\u0447\u043d\u044b\u0445\u00bb \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0439); \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0435\u0434\u0438\u043d\u044b\u0435 \u043e\u0431\u0449\u0438\u0435 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b (lr, batch/update, gamma, gae_lambda, seed-\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430) \u0442\u0430\u043c, \u0433\u0434\u0435 \u043e\u043d\u0438 \u043e\u0431\u0449\u0438\u0435 \u043f\u043e \u0441\u043c\u044b\u0441\u043b\u0443. \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u2014 \u0434\u0435\u0444\u043e\u043b\u0442\u044b `ppo/config.py` \u0438 `iql`/`qmix` config. \u041e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c eval-\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b.\n- **Seeds**: 3 seed\u2019\u0430 \u043d\u0430 (\u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c \u00d7 \u043a\u0430\u0440\u0442\u0443), \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u0434\u043b\u044f \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f; \u0435\u0441\u043b\u0438 \u0440\u0435\u0441\u0443\u0440\u0441\u044b \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u044e\u0442 \u2014 5.\n- **\u0427\u0430\u0441\u0442\u043e\u0442\u0430 eval**: \u043a\u0430\u0436\u0434\u044b\u0435 N_updates (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043a\u0430\u0436\u0434\u044b\u0435 100 PPO-updates \u0438\u043b\u0438 ~50k timesteps) \u043f\u0440\u043e\u0433\u043e\u043d K=16\u201332 eval-\u044d\u043f\u0438\u0437\u043e\u0434\u043e\u0432; \u0432\u0438\u043d\u0440\u0435\u0439\u0442 = \u0434\u043e\u043b\u044f \u043f\u043e\u0431\u0435\u0434, \u0443\u0441\u0440\u0435\u0434\u043d\u0435\u043d\u0438\u0435 \u043f\u043e eval-\u044d\u043f\u0438\u0437\u043e\u0434\u0430\u043c, \u0437\u0430\u0442\u0435\u043c \u043f\u043e seed\u2019\u0430\u043c.\n- **\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438**: \u043e\u0431\u0449\u0438\u0435 seeds; \u043e\u0431\u0449\u0438\u0439 \u0431\u044e\u0434\u0436\u0435\u0442 timesteps (\u043d\u0430\u043f\u0440., 2M, \u0438 wall-clock-\u043a\u0430\u043f); \u0435\u0434\u0438\u043d\u0430\u044f eval-\u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 (\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0447\u0438\u0441\u043b\u043e eval-\u044d\u043f\u0438\u0437\u043e\u0434\u043e\u0432, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 eval-seeds, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0432\u044b\u0431\u043e\u0440\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u2014 **greedy/argmax \u0434\u043b\u044f \u043e\u0431\u043e\u0438\u0445**, \u0435\u0441\u043b\u0438 \u044d\u0442\u043e\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442 \u0441\u0430\u043c \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c \u2014 \u043f\u0443\u043d\u043a\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438); \u043e\u0434\u043d\u0430 \u0438 \u0442\u0430 \u0436\u0435 \u043c\u0430\u0448\u0438\u043d\u0430/\u043f\u0440\u043e\u0446\u0435\u0441\u0441, `time.perf_counter` \u0432\u043d\u0435 warmup; \u0435\u0434\u0438\u043d\u0430\u044f \u043d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u043a\u0430 \u043d\u0430\u0433\u0440\u0430\u0434 (\u043e\u0431\u0430 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442 \u0448\u0442\u0430\u0442\u043d\u0443\u044e SMAX-\u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e).\n- **\u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430**: \u043a\u0440\u0438\u0432\u044b\u0435 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f win rate vs timesteps \u0438 vs wall-clock; \u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u044b (95%) \u043f\u043e seed\u2019\u0430\u043c; \u0434\u0432\u0443\u0445\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u044f\u044f \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u043d\u0430 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0442\u043e\u0447\u043a\u0430\u0445 (Mann\u2013Whitney U \u043d\u0430 3\u20135 seeds \u0438\u043b\u0438 bootstrap); \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u00abSPS, timesteps \u0434\u043e \u043f\u043e\u0440\u043e\u0433\u0430, wall-clock \u0434\u043e \u043f\u043e\u0440\u043e\u0433\u0430, \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 win rate\u00bb; \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 robus\u043d\u043e\u0441\u0442\u044c \u043a seed.\n\n### 3. \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 (\u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c)\n1. **\u041a\u0430\u043a\u043e\u0439 Q-learning**: \u0431\u0430\u0437\u043e\u0432\u044b\u0439 = **IQL** (\u0435\u0441\u0442\u044c \u0442\u043e\u0447\u043d\u043e). QMIX \u2014 \u00ab\u0435\u0441\u043b\u0438 \u0435\u0441\u0442\u044c \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438\u00bb; \u0432\u044b\u0432\u043e\u0434 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u0434\u043b\u044f \u00abvalue-based \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0439\u00bb \u0438, \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e, \u00abvalue-decomposition\u00bb. (\u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c)\n2. **CPU-only**: GPU \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d, 224 CPU. JAX \u043d\u0430 CPU \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442, \u043d\u043e wall-clock/SPS \u043a\u0430\u0440\u0434\u0438\u043d\u0430\u043b\u044c\u043d\u043e \u0437\u0430\u0432\u0438\u0441\u044f\u0442 \u043e\u0442 \u044f\u0434\u0440\u0430/\u0447\u0438\u0441\u043b\u0430 envs; \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0432\u0435\u0434\u0451\u043c \u043d\u0430 **\u043e\u0434\u043d\u043e\u0439 \u043c\u0430\u0448\u0438\u043d\u0435, \u043e\u0434\u043d\u0438\u043c \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u043c**, \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0447\u0438\u0441\u043b\u043e envs \u0438 \u0430\u0444\u0444\u0438\u043d\u0438\u0442\u0438. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c **\u0438\u0441\u0442\u0438\u043d\u043d\u044b\u0435 \u00ab\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u043c\u044b\u0435\u00bb SPS \u0438\u0437 paper \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u044b \u043d\u0430 GPU** \u2192 \u043d\u0430\u0448\u0438 SPS \u043d\u0435 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u044b \u0441 \u0442\u0430\u0431\u043b\u0438\u0446\u0430\u043c\u0438 paper, \u0442\u043e\u043b\u044c\u043a\u043e \u043c\u0435\u0436\u0434\u0443 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430\u043c\u0438 \u0432 \u043d\u0430\u0448\u0435\u043c \u043f\u0440\u043e\u0433\u043e\u043d\u0435. (\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435/\u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442)\n3. **\u0411\u044e\u0434\u0436\u0435\u0442**: design-only, \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u0433\u043e\u043d \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f; \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0431\u044e\u0434\u0436\u0435\u0442 2M timesteps \u043d\u0430 \u043a\u0430\u0440\u0442\u0443, wall-clock-\u043a\u0430\u043f (\u043d\u0430\u043f\u0440., 24\u0447 \u043d\u0430 \u043f\u0430\u0440\u0443 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u00d7\u043a\u0430\u0440\u0442\u0430\u00d7seed), \u0447\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u0434\u0438\u0437\u0430\u0439\u043d \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u044b\u043c.\n4. **\u0415\u0441\u043b\u0438 \u0433\u043e\u0442\u043e\u0432\u043e\u0433\u043e Q-learning \u0432 \u0440\u0435\u043f\u043e \u043d\u0435\u0442** (IQL/\u0432\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0444\u0430\u0439\u043b\u044b \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442 \u0438\u043b\u0438 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u044e\u0442\u0441\u044f \u043d\u0430 CPU \u0431\u0435\u0437 GPU): \u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u043d\u0430 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 IQL-\u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0432 JAX \u0438\u0437 JaxMARL-\u043f\u0440\u0438\u043c\u0438\u0442\u0438\u0432\u043e\u0432 \u0441 \u0442\u0435\u043c\u0438 \u0436\u0435 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0430\u043c\u0438, \u0438\u043b\u0438 \u0441\u0443\u0436\u0435\u043d\u0438\u0435 \u0434\u043e PPO vs Q-learning \u043d\u0430 \u043c\u0435\u043d\u044c\u0448\u0435\u043c \u043d\u0430\u0431\u043e\u0440\u0435 \u043a\u0430\u0440\u0442 \u2014 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a contingency.\n5. **\u0422\u043e\u0447\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0430 \u043d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u043a\u0438 \u043d\u0430\u0433\u0440\u0430\u0434/\u0432\u0438\u043d\u0440\u0435\u0439\u0442\u0430 \u0438 \u0441\u043e\u0441\u0442\u0430\u0432 \u043a\u0430\u0440\u0442** \u2014 \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u044b \u00ab\u043f\u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430\u043c, \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0441\u0432\u0435\u0440\u043a\u0438 \u0441 \u043a\u043e\u0434\u043e\u043c\u00bb.\n\n### \u041f\u0443\u043d\u043a\u0442\u044b, \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u043c\u044b\u0435 \u043f\u043e \u0438\u0441\u0445\u043e\u0434\u043d\u0438\u043a\u0430\u043c (\u043a\u0430\u043a \u0442\u043e\u043b\u044c\u043a\u043e \u0440\u0435\u043f\u043e \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d) vs \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f\n- **\u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u043c\u043e \u043f\u043e \u0438\u0441\u0445\u043e\u0434\u043d\u0438\u043a\u0430\u043c**: \u043d\u0430\u043b\u0438\u0447\u0438\u0435 `algorithms/ppo`, `algorithms/iql`, \u043d\u0430\u043b\u0438\u0447\u0438\u0435 QMIX; \u0441\u043f\u0438\u0441\u043e\u043a `MapName`; \u043a\u0430\u043a \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f eval-\u0432\u0438\u043d\u0440\u0435\u0439\u0442 \u0438 \u043d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u043a\u0430 \u043d\u0430\u0433\u0440\u0430\u0434; \u0434\u0435\u0444\u043e\u043b\u0442\u043d\u044b\u0435 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b; \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0432\u044b\u0431\u043e\u0440\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0432 eval; \u0435\u0441\u0442\u044c \u043b\u0438 \u0432 SMAX `normalize_reward`.\n- **\u041e\u0441\u0442\u0430\u043d\u0443\u0442\u0441\u044f \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f\u043c\u0438 \u0432 \u044d\u0442\u043e\u043c \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 (\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d)**: \u0432\u044b\u0448\u0435\u0443\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0435 \u0434\u0435\u0442\u0430\u043b\u0438, \u0442\u043e\u0447\u043d\u044b\u0435 \u0438\u043c\u0435\u043d\u0430 \u0444\u0430\u0439\u043b\u043e\u0432, \u0434\u043e\u0441\u0442\u0438\u0436\u0438\u043c\u043e\u0441\u0442\u044c \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u044b\u0445 \u043a\u0430\u0440\u0442, \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 SPS \u043d\u0430 CPU, \u0432\u0440\u0435\u043c\u044f \u0434\u043e \u043f\u043e\u0440\u043e\u0433\u0430.", "evidence": "\u0424\u0430\u043a\u0442\u044b \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e\u0439 \u0441\u0440\u0435\u0434\u044b: `/workspace` \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e `task.json` (\u00abDesign-only task; repositories and compute are not required\u00bb); `find / -iname '*jaxmarl*'` \u0438 `*smax*` \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043d\u0430\u0448\u043b\u0438; `.git`-\u043a\u0430\u0442\u0430\u043b\u043e\u0433\u043e\u0432 \u043d\u0435\u0442; `curl github.com` \u2192 NET_DOWN; Python 3.14.4, GPU \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 (gpu_enabled=false, 224 CPU). \u0422.\u0435. \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0438\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u0432 \u044d\u0442\u043e\u0439 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430 \u2014 \u0434\u0438\u0437\u0430\u0439\u043d \u043e\u043f\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 JaxMARL/SMAX (\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 `algorithms/ppo`, `algorithms/iql`, `examples/smax_ppo.py`, \u044d\u043d\u0430\u043c \u043a\u0430\u0440\u0442 SMAX, eval-\u0432\u0438\u